/* Shared offline localization. Catalogs are generated from res/config/locales. */
(function(root){
'use strict';
if(root.PinballI18n)return;
function create(catalogs,storage,language=root.navigator?.languages?.[0]||root.navigator?.language||'en'){
 const fallback='zh-Hant',listeners=new Set(),supported=Object.freeze(['zh-Hant','en','ja']);
 const normalize=value=>supported.includes(value)?value:fallback;
 const systemLanguage=String(language).trim().toLowerCase().split(/[-_]/)[0];
 let locale=systemLanguage==='zh'?'zh-Hant':systemLanguage==='ja'?'ja':'en';
 try{const saved=storage?.getItem('pinball-language');if(supported.includes(saved))locale=saved;}catch{}
 function t(key,params={}){
  const message=language=>Object.hasOwn(catalogs[language]||{},key)?catalogs[language][key]:undefined;
  const text=message(locale)??message(fallback)??key;
  return text.replace(/\{(\w+)\}/g,(match,name)=>Object.hasOwn(params,name)?String(params[name]):match);
 }
 function apply(element){
  if(!element)return;
  const nodes=[...(element.matches?.('[data-i18n],[data-i18n-aria-label],[data-i18n-title]')?[element]:[]),...element.querySelectorAll('[data-i18n],[data-i18n-aria-label],[data-i18n-title]')];
  for(const node of nodes){
   const key=node.getAttribute('data-i18n');if(key)node.textContent=t(key);
   for(const attribute of ['aria-label','title']){const key=node.getAttribute('data-i18n-'+attribute);if(key)node.setAttribute(attribute,t(key));}
  }
 }
 return {create,supported,get locale(){return locale;},t,apply,
  setLocale(value){const next=normalize(value);try{storage?.setItem('pinball-language',next);}catch{}if(next===locale)return;locale=next;for(const listener of listeners)listener(locale);},
  onChange(listener,{signal}={}){if(signal?.aborted)return ()=>{};listeners.add(listener);const off=()=>listeners.delete(listener);signal?.addEventListener('abort',off,{once:true});return off;}
 };
}
let storage;try{storage=root.localStorage;}catch{}
root.PinballI18n=create(root.PinballLocales||{},storage);
if(typeof module!=='undefined'&&module.exports)module.exports={create};
})(globalThis);

/* Shared game events -> optional Android haptics. No bridge means no vibration. */
(function(root){
'use strict';
function create({bridge,storage,now=()=>performance.now(),foreground=()=>true}){
 const priorities={tap:1,hit:2,launch:3,reward:4,attack:4,drain:5};
 const events={'score':'hit','score-hit':'hit','slingshot-hit':'hit','flipper-hit':'tap',
  launch:'launch',release:'launch',kickback:'launch',capture:'tap',
  'configured-attack':'attack','target-group-complete':'reward','multiball-awarded':'reward',
  'extra-life-awarded':'reward',drain:'drain','game-over':'drain'};
 let enabled=true,last=-Infinity,priority=0;
 try{enabled=storage?.getItem('pinball-haptics')!=='off';}catch{}
 const available=()=>typeof bridge()?.postMessage==='function';
 function stop(){try{bridge()?.postMessage('stop');}catch{}}
 function play(kind){
  if(!enabled||!foreground()||!available()||!Object.hasOwn(priorities,kind))return false;
  const time=now(),next=priorities[kind];
  if(time-last<90&&next<=priority)return false;
  try{bridge().postMessage(kind);last=time;priority=next;return true;}catch{return false;}
 }
 return Object.freeze({available,get enabled(){return enabled;},play,stop,
  setEnabled(value){enabled=!!value;try{storage?.setItem('pinball-haptics',enabled?'on':'off');}catch{}if(!enabled)stop();},
  onEvent(event,game){if(!game?.paused&&events[event.type])return play(events[event.type]);return false;}
 });
}
if(typeof module!=='undefined'&&module.exports){module.exports={create};return;}
if(root.PinballHaptics)return;
let storage;try{storage=root.localStorage;}catch{}
root.PinballHaptics=create({bridge:()=>root.AndroidHaptics,storage,foreground:()=>!root.document.hidden});
root.document.addEventListener('visibilitychange',()=>{if(root.document.hidden)root.PinballHaptics.stop();});
})(globalThis);

/* Native Play ownership is separate from prototype web purchase saves. */
(function(root){
'use strict';
function create(bridge){
 let serial=0,state={configured:false,ready:false,status:'loading',products:{},owned:[],pending:[]};
 const listeners=new Set(),requests=new Map();
 function receive(value){
  try{if(typeof value==='string')value=JSON.parse(value);}catch{return;}
  if(!value||typeof value!=='object')return;
  const update=value.state||(value.type==='state'?value:null);
  if(update&&Array.isArray(update.owned)&&Array.isArray(update.pending)&&update.products&&typeof update.products==='object'){
   state={configured:update.configured===true,ready:update.ready===true,status:update.status,products:update.products,owned:update.owned.filter(x=>['steampunk','cosmic-dessert','ragnarok'].includes(x)),pending:update.pending};
   for(const fn of listeners)fn(state);
  }
  const request=requests.get(value.id);if(!request)return;
  clearTimeout(request.timer);requests.delete(value.id);
  request.resolve({purchased:value.result==='purchased',pending:value.result==='pending',result:value.result});
 }
 bridge.onmessage=e=>receive(e.data);
 function request(action,key){return new Promise((resolve,reject)=>{
  const id='billing-'+(++serial),timer=setTimeout(()=>{requests.delete(id);reject(Error('Billing request timed out'));},action==='purchase'?180000:30000);
  requests.set(id,{resolve,reject,timer});
  try{bridge.postMessage(JSON.stringify({id,action,...(key?{key}:{})}));}catch(error){clearTimeout(timer);requests.delete(id);reject(error);}
 });}
 return {get state(){return state;},receive,refresh:()=>request('refresh'),purchase:key=>request('purchase',key),
  onChange(fn){listeners.add(fn);return ()=>listeners.delete(fn);}};
}
if(typeof module!=='undefined'&&module.exports)module.exports={create};else root.PlayBilling={create};
})(globalThis);

