  const clock=()=>(suspended?pausedAt:performance.now())-pausedTotal;
  const absolute=value=>new URL(value,baseURL).href;
  const imageURL=(value,relativeTo=baseURL)=>window.PinballRuntimeImages?.resolve(value,relativeTo)??new URL(value,relativeTo).href;
  const scopedCSS=(css,url=baseURL)=>css.replace(/\bhtml\b/g,':host').replace(/\bbody\b/g,'#view-body').replace(/\biframe\b/g,'pinball-view').replace(/url\((['"]?)([^)'"\s]+)\1\)/g,(_,q,path)=>`url("${imageURL(path,url)}")`);
