  function listen(type,fn,options){(['message','pagehide'].includes(type)?bus:['keydown','keyup','pointerdown'].includes(type)?shadow:window).addEventListener(type,fn,{...(typeof options==='boolean'?{capture:options}:options),signal:abort.signal});}
