      sounds.add(element);element.muted=appSettings?.sound===false;
      const volume=Object.getOwnPropertyDescriptor(HTMLMediaElement.prototype,'volume');
      mediaVolumes.set(element,volume.get.call(element));
      Object.defineProperty(element,'volume',{configurable:true,get(){return mediaVolumes.get(this)},set(value){mediaVolumes.set(this,value);volume.set.call(this,value*masterVolume())}});
      volume.set.call(element,mediaVolumes.get(element)*masterVolume());
