      if(key==='body'||key==='documentElement')return body;
      if(key==='head')return {append(...nodes){for(const node of nodes){if(node.tagName==='STYLE')node.textContent=scopedCSS(node.textContent);shadow.append(node);}}};
      if(key==='baseURI'||key==='URL')return baseURL.href;
      if(key==='querySelector')return selector=>shadow.querySelector(selector);
      if(key==='querySelectorAll')return selector=>shadow.querySelectorAll(selector);
      if(key==='getElementById')return id=>shadow.getElementById(id);
      if(key==='getAnimations')return ()=>body.getAnimations({subtree:true});
      if(key==='createElement')return (tag,...args)=>tag.toLowerCase()==='iframe'?createPanel():resourceElement(document.createElement(tag,...args));
