 for(const o of layout.objects){o.label=UnlockLayout.label(o);if(o.id==='single')o.price=window.PinballPlatform==='android'?(playBilling?.state.products[unlockTheme]?.price||''):money(unlockPrices.tables[unlockTheme]);if(o.id==='all')o.price=window.PinballPlatform==='android'?(playBilling?.state.products.all?.price||''):money(unlockPrices.all);}
