async function requestPurchase(kind){
 if(window.PinballPlatform==='android'&&!playBilling){unlockStatus.textContent=PinballI18n.t('purchase.notAvailable');return;}
 if(purchasePending||!unlockTheme||ownedTables.has(unlockTheme)||(kind==='all'&&allPurchaseDisabled()))return;
 const tables=kind==='all'?remainingPaidTables():[unlockTheme];
 purchasePending=true;buildUnlockActions();unlockStatus.textContent=PinballI18n.t('purchase.processing');
 try{
  // Default prototype purchases persist locally; a host handler can replace them.
  const result=playBilling?await playBilling.purchase(billingKey(kind)):await (purchaseHandler||simulatePurchase)({kind,themeId:unlockTheme,tables:[...tables],amount:kind==='all'?unlockPrices.all:unlockPrices.tables[unlockTheme],currency:unlockPrices.currency});
  if(result?.purchased===true){
   if(playBilling&&!tables.every(id=>playBilling.state.owned.includes(id)))throw Error('Ownership not verified');
   if(!playBilling){const purchased=[...new Set([...mainSave.purchased,...tables])];MainSave.write(localStorage,{...mainSave,purchased});mainSave.purchased=purchased;}
   for(const id of tables){ownedTables.add(id);pendingUnlockTables.add(id);}
   purchasePending=false;closeUnlock();purchasePending=true;transitioning=true;menu.inert=true;settingsButton.hidden=true;
   buildMenuActions();
   try{for(const id of tables){await animateMenuUnlock({themeIds:[id]});pendingUnlockTables.delete(id);buildMenuActions();drawMenu();}}
   finally{pendingUnlockTables.clear();transitioning=false;menu.inert=settingsOpen;settingsButton.hidden=settingsOpen;buildMenuActions();drawMenu();}
  }
  else unlockStatus.textContent=PinballI18n.t(result?.pending?'purchase.pending':(result?.result==='cancelled'||!playBilling)?'purchase.cancelled':'purchase.failed');
 }catch{unlockStatus.textContent=PinballI18n.t('purchase.failed');}
 finally{purchasePending=false;if(!unlockDialog.hidden){buildUnlockActions();unlockActions.querySelector('[data-unlock="single"]').focus();}}
}
function setOwnedTables(ids){
 if(window.PinballPlatform==='android')return; // Native receipt updates use the private billing listener.
 if(purchasePending)throw Error(PinballI18n.t('purchase.busy'));
 ownedTables.clear();for(const id of ids)if(Object.hasOwn(unlockPrices.tables,id))ownedTables.add(id);
 if(unlockTheme&&ownedTables.has(unlockTheme))closeUnlock();
 else if(!unlockDialog.hidden){if(window.PinballPlatform==='android')unlockStatus.textContent=billingStatus();buildUnlockActions();}
 buildMenuActions();drawMenu();
}
