 button.setAttribute('aria-label',isOpenTheme?PinballI18n.t('menu.start',{name:themeName(o.themeId)}):isBossStage?PinballI18n.t('menu.stage',{stage:o.stage}):isEndless?PinballI18n.t('menu.endless'):isSound?PinballI18n.t('menu.sound'):PinballI18n.t('menu.unavailable'));
 if(isOpenTheme){button.dataset.theme=o.themeId;button.disabled=pendingUnlockTables.has(o.themeId);button.onclick=()=>switchMenu(o.themeId,o.themeId);}
 else if(menuMode==='main'&&o.themeId==='touhou-black-knight-2000'){button.dataset.theme=o.themeId;button.disabled=true;button.title=PinballI18n.t('menu.touhou2Locked');button.setAttribute('aria-label',button.title);}
 else if(menuMode==='main'&&Object.hasOwn(unlockPrices.tables,o.themeId)){button.dataset.theme=o.themeId;const owned=ownedTables.has(o.themeId);button.disabled=pendingUnlockTables.has(o.themeId);button.setAttribute('aria-label',PinballI18n.t(owned?'menu.start':'menu.unlock',{name:themeName(o.themeId)}));button.onclick=()=>owned?switchMenu(o.themeId,o.themeId):openUnlock(o.themeId);}
